<?php

function fib(int $n): int
{
    [$a, $b] = [0, 1];
    for ($i = 0; $i < $n; $i++) {
        [$a, $b] = [$b, $a + $b];
    }
    return $a;
}

function gcd(int $a, int $b): int
{
    while ($b !== 0) {
        [$a, $b] = [$b, $a % $b];
    }
    return $a;
}

function isPrime(int $n): bool
{
    if ($n < 2) {
        return false;
    }
    for ($i = 2; $i * $i <= $n; $i++) {
        if ($n % $i === 0) {
            return false;
        }
    }
    return true;
}

function binarySearch(array $items, int $target): int
{
    $lo = 0;
    $hi = count($items) - 1;
    while ($lo <= $hi) {
        $mid = intdiv($lo + $hi, 2);
        if ($items[$mid] === $target) {
            return $mid;
        }
        if ($items[$mid] < $target) {
            $lo = $mid + 1;
        } else {
            $hi = $mid - 1;
        }
    }
    return -1;
}

$primes = array_values(array_filter(range(2, 49), 'isPrime'));
$squares = array_map(fn (int $n): int => $n * $n, range(1, 19));

echo 'fib(10) = ', fib(10), PHP_EOL;
echo 'gcd(54, 24) = ', gcd(54, 24), PHP_EOL;
echo 'primes: ', implode(' ', $primes), PHP_EOL;
echo 'index of 144: ', binarySearch($squares, 144), PHP_EOL;

